import unittest
from solution import count_word_occurrences

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(count_word_occurrences("a b a"), {"a": 2, "b": 1})
    def test_case(self):
        self.assertEqual(count_word_occurrences("Hi hi HI"), {"hi": 3})
    def test_empty(self):
        self.assertEqual(count_word_occurrences(""), {})
    def test_whitespace(self):
        self.assertEqual(count_word_occurrences("a  b\ta\nb"), {"a": 2, "b": 2})
    def test_single(self):
        self.assertEqual(count_word_occurrences("solo"), {"solo": 1})
